import AVFAudio
import Foundation

enum CallingEvent {
    case connected(UUID, Date)
    case ended(UUID, PhoneCallOutcome, Date)
    case assessmentStarted(UUID)
    case assessed(UUID, Voice)
    case deepfakeAssessment(UUID, DeepfakeAssessment)
    case transcriptAssessment(UUID, TranscriptAssessment)
    case failed(UUID, String)
    /// A call is waiting for this phone: its call UUID, the caller's number as the service
    /// saw it (may be empty) and an optional caller name. Only backends that ring without
    /// PushKit emit this; the coordinator reports it to CallKit.
    case incoming(UUID, String, String?)
    /// A backend that rings without PushKit cannot wait for calls and trying again will not
    /// help (its access was refused or has expired). The text is shown to the person using
    /// the phone. Temporary failures such as no network are retried quietly and not reported.
    case incomingCallsUnavailable(String)
}

/// Implement with the signaling/media provider; `LiveKitCallingBackend` is the LiveKit
/// implementation. Emitting `connected` must
/// mean media is actually connected. Assessment events must refer to that call's
/// remote media stream; they must never contain a sample or locally timed result.
/// `start` returns after signaling is accepted; `answer` waits until the incoming
/// session is ready to connect (including any concurrent `prepareIncoming`). Audio
/// starts only in `activateAudio`; reset/end must cancel all work for that call.
///
/// Incoming calls arrive one of two ways. A backend with `usesVoIPPush` is woken by
/// PushKit. A backend without it is told to `listenForIncomingCalls` while the app is
/// open and emits `incoming`; `prepareIncoming` follows once CallKit accepts the call.
/// `end` for a call that was announced but never rang (CallKit refused it, or another
/// call was active) only makes the backend forget that call.
@MainActor
protocol CallingBackend: AnyObject {
    var isConfigured: Bool { get }
    /// True when incoming calls reach the app as PushKit VoIP pushes. When false the
    /// coordinator never creates a PKPushRegistry, which needs the push entitlement.
    var usesVoIPPush: Bool { get }
    /// False for an inbound-only service; outgoing calls then stay with the system dialer.
    var canPlaceOutgoingCalls: Bool { get }
    /// False when the service cannot hold a call or send keypad tones. The in-call screen then
    /// leaves those two controls out instead of offering buttons that can only fail.
    var supportsHoldAndKeypad: Bool { get }
    var onEvent: ((CallingEvent) -> Void)? { get set }
    /// Called at launch and every time the app returns to the foreground.
    func listenForIncomingCalls()
    func start(callID: UUID, number: String) async throws
    func prepareIncoming(callID: UUID, number: String) async throws
    func answer(callID: UUID) async throws
    func end(callID: UUID) async throws
    func setMuted(_ muted: Bool, callID: UUID) async throws
    func setHeld(_ held: Bool, callID: UUID) async throws
    func sendDTMF(_ digits: String, callID: UUID) async throws
    func registerVoIPToken(_ token: Data?) async throws
    func activateAudio(_ session: AVAudioSession)
    func deactivateAudio(_ session: AVAudioSession)
    func reset()
}

@MainActor
final class UnconnectedCallingBackend: CallingBackend {
    var isConfigured: Bool { false }
    var usesVoIPPush: Bool { false }
    var canPlaceOutgoingCalls: Bool { false }
    var supportsHoldAndKeypad: Bool { false }
    var onEvent: ((CallingEvent) -> Void)?
    func listenForIncomingCalls() {}
    func start(callID: UUID, number: String) async throws { throw PhoneError.serviceUnavailable }
    func prepareIncoming(callID: UUID, number: String) async throws { throw PhoneError.serviceUnavailable }
    func answer(callID: UUID) async throws { throw PhoneError.serviceUnavailable }
    func end(callID: UUID) async throws { throw PhoneError.serviceUnavailable }
    func setMuted(_ muted: Bool, callID: UUID) async throws { throw PhoneError.serviceUnavailable }
    func setHeld(_ held: Bool, callID: UUID) async throws { throw PhoneError.serviceUnavailable }
    func sendDTMF(_ digits: String, callID: UUID) async throws { throw PhoneError.serviceUnavailable }
    func registerVoIPToken(_ token: Data?) async throws { throw PhoneError.serviceUnavailable }
    func activateAudio(_ session: AVAudioSession) {}
    func deactivateAudio(_ session: AVAudioSession) {}
    func reset() {}
}

struct VoicemailMessage: Identifiable, Equatable {
    let id: String
    let caller: Person
    let date: Date
    let duration: Int
    let isRead: Bool
    let audioURL: URL
}

@MainActor
protocol VoicemailBackend {
    var isConfigured: Bool { get }
    func messages() async throws -> [VoicemailMessage]
    func markRead(id: String) async throws
    func delete(id: String) async throws
}

@MainActor
struct UnconnectedVoicemailBackend: VoicemailBackend {
    var isConfigured: Bool { false }
    func messages() async throws -> [VoicemailMessage] { throw PhoneError.serviceUnavailable }
    func markRead(id: String) async throws { throw PhoneError.serviceUnavailable }
    func delete(id: String) async throws { throw PhoneError.serviceUnavailable }
}

/// Calling uses LiveKit once CALLSHIELD_LIVEKIT_HOST and CALLSHIELD_LOBBY_TOKEN are set in
/// the gitignored Configuration/Local.xcconfig. Replace the voicemail factory when that
/// service is available. Production never falls back to the demo's sample data.
@MainActor
enum AppServices {
    static func makeCallingBackend() -> CallingBackend {
        // Tests never open a network connection, even on a Mac whose Local.xcconfig is filled in.
        if ProcessInfo.processInfo.environment["XCTestConfigurationFilePath"] != nil
            || NSClassFromString("XCTestCase") != nil { return UnconnectedCallingBackend() }
        #if DEBUG
        let arguments = ProcessInfo.processInfo.arguments
        if arguments.contains("--ui-test-demo") || arguments.contains("--ui-test-production") { return UnconnectedCallingBackend() }
        #endif
        guard let host = AppConfiguration.liveKitHost, let lobbyToken = AppConfiguration.lobbyToken else {
            return UnconnectedCallingBackend()
        }
        return LiveKitCallingBackend(host: host, lobbyToken: lobbyToken)
    }
    static func makeVoicemailBackend() -> VoicemailBackend { UnconnectedVoicemailBackend() }
}

import Contacts
import Foundation

enum ContactsAccess: Equatable { case notRequested, denied, available, limited }

protocol PhoneContactsService {
    var access: ContactsAccess { get }
    func requestAccess() async throws -> Bool
    func fetch() async throws -> [Person]
}

final class DeviceContactsService: PhoneContactsService {
    private let store = CNContactStore()
    var access: ContactsAccess {
        let status = CNContactStore.authorizationStatus(for: .contacts)
        if #available(iOS 18, *), status == .limited { return .limited }
        switch status {
        case .authorized: return .available
        case .notDetermined: return .notRequested
        default: return .denied
        }
    }
    func requestAccess() async throws -> Bool { try await store.requestAccess(for: .contacts) }
    func fetch() async throws -> [Person] {
        guard access == .available || access == .limited else { return [] }
        return try await withCheckedThrowingContinuation { continuation in
            DispatchQueue.global(qos: .userInitiated).async {
                do {
                    let store = CNContactStore()
                    var result: [Person] = []
                    var seen = Set<String>()
                    let request = CNContactFetchRequest(keysToFetch: [CNContactFormatter.descriptorForRequiredKeys(for: .fullName), CNContactPhoneNumbersKey as CNKeyDescriptor])
                    request.sortOrder = .userDefault
                    try store.enumerateContacts(with: request) { contact, _ in
                        let name = CNContactFormatter.string(from: contact, style: .fullName)
                        for phone in contact.phoneNumbers {
                            guard let number = try? PhoneNumber.normalized(phone.value.stringValue), seen.insert(number).inserted else { continue }
                            result.append(PhoneNumber.person(number, name: name))
                        }
                    }
                    continuation.resume(returning: result)
                } catch { continuation.resume(throwing: error) }
            }
        }
    }
}

import Foundation

/// Voice evidence is separate from transcript/scam risk. No audio is stored.
struct DeepfakeAssessment: Codable, Equatable {
    enum State: String, Codable { case waiting, analyzing, human, ai, uncertain, unavailable }
    let state: State
    let updatedAt: Date
    var windows: Int = 0

    var voice: Voice {
        switch state {
        case .human: return .human
        case .ai: return .ai
        case .analyzing: return .analyzing
        default: return .unknown
        }
    }
    var historyMessage: String {
        switch state {
        case .waiting: return "Not enough caller speech for a voice assessment."
        case .analyzing: return "The call ended before a voice result was available."
        case .unavailable: return "Voice analysis was unavailable for this call."
        default: return message
        }
    }
    var message: String {
        switch state {
        case .waiting: return "Waiting for enough caller speech…"
        case .analyzing: return "Checking the caller’s voice…"
        case .human: return "This voice appears to be human."
        case .ai: return "This voice may be AI-generated. Verify the caller before sharing information."
        case .uncertain: return "The voice result is uncertain. Keep listening."
        case .unavailable: return "Voice analysis is unavailable. Your call can continue."
        }
    }
}

/// Versioned contract produced by LiveKit Setup/risk_protocol.py. Strict decoding keeps
/// malformed data, stub scores and the combined transcript level out of voice labels.
struct DeepfakeUpdate: Decodable {
    static let topic = "scam-guard.risk"
    let schema: Int
    let type: String
    let room: String
    let callerIdentity: String
    let streamID: UUID
    let sequence: Int
    let model: String
    let state: DeepfakeAssessment.State?
    let deepfake: Evidence?

    struct Evidence: Decodable {
        let level: String
        let updates: Int
        let human_steps: Int
        let p_last: Double
        let p_smoothed: Double
        let logit_last: Double
        let logit_smoothed: Double
    }

    static func decode(_ data: Data) -> DeepfakeUpdate? {
        guard data.count <= 16_384, let value = try? JSONDecoder().decode(Self.self, from: data),
              value.schema == 1, value.sequence > 0, !value.room.isEmpty, !value.callerIdentity.isEmpty,
              ["real", "stub"].contains(value.model) else { return nil }
        if value.type == "status" {
            guard let state = value.state, [.waiting, .analyzing, .unavailable].contains(state) else { return nil }
        } else if value.type == "risk" {
            guard let e = value.deepfake, ["listening", "elevated", "high"].contains(e.level),
                  e.updates > 0, e.human_steps >= 0, e.human_steps <= e.updates,
                  (0...1).contains(e.p_last), (0...1).contains(e.p_smoothed),
                  e.logit_last.isFinite, e.logit_smoothed.isFinite else { return nil }
        } else { return nil }
        return value
    }

    func assessment(at date: Date) -> DeepfakeAssessment {
        guard model == "real" else { return DeepfakeAssessment(state: .unavailable, updatedAt: date) }
        guard type == "risk", let e = deepfake else {
            return DeepfakeAssessment(state: state ?? .unavailable, updatedAt: date)
        }
        let result: DeepfakeAssessment.State
        if e.level == "high", e.updates >= 3 { result = .ai }
        else if e.level == "elevated" { result = .uncertain }
        else if e.level == "listening", e.human_steps >= 3 { result = .human }
        else { result = .analyzing }
        return DeepfakeAssessment(state: result, updatedAt: date, windows: e.updates)
    }
}

/// One per call; rejects duplicate/out-of-order messages and retired agent streams,
/// and expires results when heartbeats stop.
struct DeepfakeMonitor {
    static let timeout: TimeInterval = 12
    private var streamID: UUID?
    private var retiredStreams = Set<UUID>()
    private var sequence = 0
    private(set) var latest: DeepfakeAssessment?

    mutating func receive(_ update: DeepfakeUpdate, room: String, callerIdentity: String,
                          isAgent: Bool, at date: Date) -> DeepfakeAssessment? {
        guard isAgent, update.room == room, update.callerIdentity == callerIdentity,
              !retiredStreams.contains(update.streamID) else { return nil }
        if streamID != update.streamID {
            if let streamID { retiredStreams.insert(streamID) }
            streamID = update.streamID; sequence = 0
        }
        guard update.sequence > sequence else { return nil }
        sequence = update.sequence
        let assessment = update.assessment(at: date)
        latest = assessment
        return assessment
    }

    mutating func expire(at date: Date, connectedAt: Date) -> DeepfakeAssessment? {
        guard date.timeIntervalSince(latest?.updatedAt ?? connectedAt) >= Self.timeout,
              latest?.state != .unavailable else { return nil }
        let assessment = DeepfakeAssessment(state: .unavailable, updatedAt: date)
        latest = assessment
        return assessment
    }
}


/// Caller-language evidence stays separate from the voice/deepfake result.
struct TranscriptAssessment: Codable, Equatable {
    enum State: String, Codable { case listening, monitoring, stale, unavailable, disabled }
    let state: State
    let updatedAt: Date
    var probability: Double? = nil
    var scoredRevision: Int = 0
    var scoreAge: TimeInterval = 0

    var title: String {
        guard state == .monitoring, let probability else {
            switch state {
            case .listening: return "Listening for caller speech…"
            case .stale: return "Waiting for a fresh transcript result"
            case .disabled: return "Transcript analysis is off"
            default: return "Transcript analysis unavailable"
            }
        }
        return probability >= 0.8 ? "Possible scam language" : "No strong scam-language signal"
    }
    var message: String {
        guard state == .monitoring, let probability else {
            return state == .listening ? "The caller’s words will be checked as they speak." : "Your call can continue."
        }
        return "Scam risk score: \(Int((probability * 100).rounded()))% · update \(scoredRevision)"
    }
    var isWarning: Bool { state == .monitoring && (probability ?? 0) >= 0.8 }
}

struct TranscriptUpdate: Decodable {
    let schema: Int
    let type: String
    let room: String
    let callerIdentity: String
    let streamID: UUID
    let sequence: Int
    let model: String
    let transcript: Evidence

    struct Evidence: Decodable {
        let state: String
        let probability: Double?
        let scored_revision: Int?
        let age_sec: Double?
    }
    static func decode(_ data: Data) -> TranscriptUpdate? {
        guard data.count <= 16_384, let value = try? JSONDecoder().decode(Self.self, from: data),
              value.schema == 1, value.sequence > 0, !value.room.isEmpty, !value.callerIdentity.isEmpty,
              ["risk", "status"].contains(value.type), ["real", "stub"].contains(value.model),
              ["listening", "monitoring", "stale", "disabled", "stt_unavailable", "jev_unavailable", "audio_overrun"].contains(value.transcript.state) else { return nil }
        if value.transcript.state == "monitoring" {
            guard let p = value.transcript.probability, p.isFinite, (0...1).contains(p),
                  let revision = value.transcript.scored_revision, revision > 0,
                  let age = value.transcript.age_sec, age.isFinite, age >= 0 else { return nil }
        }
        return value
    }
    func assessment(at date: Date) -> TranscriptAssessment {
        let evidence = transcript
        let state: TranscriptAssessment.State
        if model != "real" { state = .unavailable }
        else if evidence.state == "monitoring" { state = (evidence.age_sec ?? 16) <= 15 ? .monitoring : .stale }
        else if evidence.state == "listening" { state = .listening }
        else if evidence.state == "stale" { state = .stale }
        else if evidence.state == "disabled" { state = .disabled }
        else { state = .unavailable }
        return TranscriptAssessment(state: state, updatedAt: date,
                                    probability: state == .monitoring ? evidence.probability : nil,
                                    scoredRevision: evidence.scored_revision ?? 0, scoreAge: evidence.age_sec ?? 0)
    }
}

struct TranscriptMonitor {
    private var streamID: UUID?
    private var retiredStreams = Set<UUID>()
    private var sequence = 0
    private(set) var latest: TranscriptAssessment?

    mutating func receive(_ update: TranscriptUpdate, room: String, callerIdentity: String,
                          isAgent: Bool, at date: Date) -> TranscriptAssessment? {
        guard isAgent, update.room == room, update.callerIdentity == callerIdentity,
              !retiredStreams.contains(update.streamID) else { return nil }
        if streamID != update.streamID {
            if let streamID { retiredStreams.insert(streamID) }
            streamID = update.streamID; sequence = 0
        }
        guard update.sequence > sequence else { return nil }
        sequence = update.sequence
        let result = update.assessment(at: date)
        latest = result
        return result
    }
    mutating func expire(at date: Date, connectedAt: Date) -> TranscriptAssessment? {
        let elapsed = date.timeIntervalSince(latest?.updatedAt ?? connectedAt)
        let stale = latest?.state == .monitoring && elapsed + (latest?.scoreAge ?? 0) > 15
        guard (elapsed >= 12 || stale), latest?.state != .unavailable, latest?.state != .stale else { return nil }
        let result = TranscriptAssessment(state: stale ? .stale : .unavailable, updatedAt: date)
        latest = result
        return result
    }
}

import AVFAudio
import Foundation
import LiveKit
import UIKit

/// Every audio-engine change runs on this one serial queue. `setEngineAvailability` blocks
/// its caller until WebRTC has applied it, so it must never run on the main thread.
private let liveKitAudioQueue = DispatchQueue(label: "org.callshield.livekit.audio")

private func callshieldLog(_ message: String) { print("[Callshield] \(message)") }

/// For the log only. The SDK's own description of an error can read just "Unknown", so its
/// code goes with it; the person on the call is never shown this text.
private func callshieldDetail(_ error: Error) -> String {
    guard let error = error as? LiveKitError else { return error.localizedDescription }
    return "\(error.localizedDescription) [LiveKit error \(error.type.rawValue)]"
}

/// What the person on the call sees when joining the call room or publishing the microphone
/// fails, in place of the SDK's own wording (that goes to the log).
private struct CallConnectionError: LocalizedError {
    var errorDescription: String? { "The call could not be connected." }
}

/// The "incoming call" message the scam-guard agent sends to the lobby room. It carries a
/// join token, so never print one.
struct IncomingCallInvite: Equatable {
    static let topic = "callshield.incoming"
    let callID: UUID
    let room: String
    let token: String
    let handle: String
    let callerIdentity: String
    let callerName: String?

    /// nil unless the payload is a complete invite. A missing or empty `handle` is accepted:
    /// a caller who withholds their number must still ring.
    static func decode(_ data: Data) -> IncomingCallInvite? {
        guard let object = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any],
              object["type"] as? String == "incoming_call",
              let callID = (object["callUUID"] as? String).flatMap(UUID.init(uuidString:)),
              let room = object["room"] as? String, !room.isEmpty,
              let token = object["token"] as? String, !token.isEmpty,
              let callerIdentity = object["callerIdentity"] as? String, !callerIdentity.isEmpty else { return nil }
        let name = (object["callerName"] as? String)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return IncomingCallInvite(callID: callID, room: room, token: token, handle: object["handle"] as? String ?? "",
                                  callerIdentity: callerIdentity, callerName: name.isEmpty ? nil : String(name.prefix(128)))
    }
}

/// Foreground-only ringing over LiveKit, with no PushKit. While the app is open it waits in a
/// small "lobby" room for an invite from the scam-guard agent. CallKit then rings, the app
/// joins the call room silently, and the microphone is published only when the call is
/// answered: for a LiveKit phone call, publishing audio is what answers it.
@MainActor
final class LiveKitCallingBackend: NSObject, CallingBackend, RoomDelegate {
    private struct LiveCall {
        let invite: IncomingCallInvite
        let prepare: Task<Void, Error>
        var room: Room?
        var answered = false     // microphone published
        var audioActive = false  // engine running inside CallKit's activation window
        var connected = false    // `connected` already emitted
        var connectedAt: Date?
        var detector = DeepfakeMonitor()
        var transcriptDetector = TranscriptMonitor()
    }

    let isConfigured: Bool
    var usesVoIPPush: Bool { false }
    var canPlaceOutgoingCalls: Bool { false }
    /// The call-room token has no data grant, so keypad tones would be dropped, and a phone call has no hold.
    var supportsHoldAndKeypad: Bool { false }
    var onEvent: ((CallingEvent) -> Void)?

    private let serverURL: String
    private let lobbyToken: String
    private var listening = false
    private var lobbyRejected = false // The service refused the lobby token: no retry until the next foreground.
    private var announcedRejection = false
    private var lobbyRoom: Room?
    private var lobbyConnect: Task<Void, Never>?
    private var lobbyRetry: Task<Void, Never>?
    private var invites: [UUID: IncomingCallInvite] = [:]
    private var handledCallIDs: [UUID] = []
    private var call: LiveCall?
    private var callTeardown: Task<Void, Never>?
    private var assessmentWatchdog: Task<Void, Never>?
    private var observers: [NSObjectProtocol] = []
    private var idleTimerWasDisabled: Bool?
    private var askedForMicrophone = false

    init(host: String, lobbyToken: String) {
        serverURL = "wss://" + host
        self.lobbyToken = lobbyToken
        isConfigured = !host.isEmpty && !lobbyToken.isEmpty
        super.init()
        guard isConfigured else { return }
        // LiveKit's CallKit rule: before any Room exists, stop the SDK configuring AVAudioSession
        // and hold its audio engine off. Rooms are created only after `audioQueueDrained()`.
        liveKitAudioQueue.async {
            AudioManager.shared.audioSession.isAutomaticConfigurationEnabled = false
            do { try AudioManager.shared.setEngineAvailability(.none) }
            catch { callshieldLog("could not hold the audio engine off: \(callshieldDetail(error))") }
        }
        let center = NotificationCenter.default
        observers = [
            center.addObserver(forName: UIApplication.didBecomeActiveNotification, object: nil, queue: .main) { [weak self] _ in
                Task { @MainActor in self?.appBecameActive() }
            },
            // Not willResignActive: CallKit's incoming-call UI makes the app inactive while it rings.
            center.addObserver(forName: UIApplication.didEnterBackgroundNotification, object: nil, queue: .main) { [weak self] _ in
                Task { @MainActor in self?.appEnteredBackground() }
            }
        ]
    }

    deinit { for observer in observers { NotificationCenter.default.removeObserver(observer) } }

    // MARK: - Listening

    func listenForIncomingCalls() {
        guard isConfigured else { return }
        listening = true
        guard UIApplication.shared.applicationState != .background else { return }
        // Keeping the screen awake is what makes a foreground-only ring usable for the demo.
        if idleTimerWasDisabled == nil {
            idleTimerWasDisabled = UIApplication.shared.isIdleTimerDisabled
            UIApplication.shared.isIdleTimerDisabled = true
        }
        askForMicrophoneOnce()
        lobbyRejected = false // In the foreground again: a refused token gets one more try.
        lobbyRetry?.cancel(); lobbyRetry = nil // Try now, not after the delay.
        connectLobbyIfNeeded()
    }

    /// Asked while the app is in front, because the prompt cannot appear later over the incoming-call UI.
    private func askForMicrophoneOnce() {
        guard !askedForMicrophone, UIApplication.shared.applicationState == .active,
              AVAudioSession.sharedInstance().recordPermission == .undetermined else { return }
        askedForMicrophone = true
        AVAudioSession.sharedInstance().requestRecordPermission { _ in }
    }

    private func appBecameActive() {
        if listening { listenForIncomingCalls() }
    }

    private func appEnteredBackground() {
        if let previous = idleTimerWasDisabled {
            UIApplication.shared.isIdleTimerDisabled = previous
            idleTimerWasDisabled = nil
        }
        // A ringing or connected call carries on in the background; only the idle lobby is dropped.
        guard call == nil, invites.isEmpty else { return }
        Task { @MainActor in
            await self.stopLobby()
            self.connectLobbyIfNeeded() // Does nothing unless the app is already back in front.
        }
    }

    // MARK: - Lobby

    private var wantsLobby: Bool {
        listening && !lobbyRejected && call == nil && invites.isEmpty && UIApplication.shared.applicationState != .background
    }

    private func connectLobbyIfNeeded() {
        guard wantsLobby, lobbyRoom == nil, lobbyConnect == nil, lobbyRetry == nil else { return }
        lobbyConnect = Task { @MainActor [weak self] in
            await self?.connectLobby()
            self?.lobbyConnect = nil
            self?.connectLobbyIfNeeded() // The app may have come back while a stopped attempt was unwinding.
        }
    }

    private func connectLobby() async {
        _ = await callTeardown?.value // One Room at a time: the last call room finishes disconnecting first.
        await audioQueueDrained()
        guard wantsLobby, lobbyRoom == nil else { return }
        let room = Room()
        room.add(delegate: self)
        lobbyRoom = room
        do {
            // Signalling only: nothing in the lobby is subscribed to or published.
            try await room.connect(url: serverURL, token: lobbyToken, connectOptions: ConnectOptions(autoSubscribe: false))
        } catch {
            guard lobbyRoom === room else { return } // stopLobby() got there first.
            lobbyRoom = nil
            if (error as? LiveKitError)?.type == .validation {
                // The service answered 4xx: the token is expired or wrong, and trying again cannot help. Because
                // wantsLobby is now false, connectLobbyIfNeeded() stops here too; the next foreground tries once more.
                lobbyRejected = true
                callshieldLog("lobby token refused: \(callshieldDetail(error))")
                if !announcedRejection { // Once, not on every foreground; a later successful connection re-arms it.
                    announcedRejection = true
                    onEvent?(.incomingCallsUnavailable("Callshield can’t take incoming calls right now: its access to the calling service was refused or has expired. It needs to be set up again."))
                }
                return
            }
            callshieldLog("lobby connection failed: \(callshieldDetail(error))")
            scheduleLobbyRetry()
            return
        }
        guard lobbyRoom === room else { await room.disconnect(); return }
        announcedRejection = false
        callshieldLog("lobby connected; waiting for incoming calls")
    }

    private func stopLobby() async {
        lobbyRetry?.cancel(); lobbyRetry = nil
        guard let room = lobbyRoom else { return }
        lobbyRoom = nil
        await room.disconnect()
        callshieldLog("lobby disconnected")
    }

    private func scheduleLobbyRetry() {
        guard wantsLobby, lobbyRetry == nil else { return }
        lobbyRetry = Task { @MainActor [weak self] in
            try? await Task.sleep(nanoseconds: 3_000_000_000)
            guard !Task.isCancelled, let self else { return }
            self.lobbyRetry = nil
            self.connectLobbyIfNeeded()
        }
    }

    /// Resumes after everything queued so far on the audio queue has run, which includes the
    /// engine being held off in `init`. Awaited before every `Room()`.
    private func audioQueueDrained() async {
        await withCheckedContinuation { (continuation: CheckedContinuation<Void, Never>) in
            liveKitAudioQueue.async { continuation.resume() }
        }
    }

    // MARK: - Invites

    private func receiveInvite(_ data: Data, in room: Room) {
        guard room === lobbyRoom, let onEvent else { return }
        guard let invite = IncomingCallInvite.decode(data) else { callshieldLog("ignored a malformed invite"); return }
        // The agent repeats an invite every few seconds until the call is joined or over.
        guard !handledCallIDs.contains(invite.callID), call == nil, invites.isEmpty else { return }
        handledCallIDs.append(invite.callID)
        if handledCallIDs.count > 32 { handledCallIDs.removeFirst() }
        invites[invite.callID] = invite
        callshieldLog("invite received: call \(invite.callID), handle \"\(invite.handle)\"")
        onEvent(.incoming(invite.callID, invite.handle, invite.callerName))
    }

    private func preparation(for callID: UUID) throws -> Task<Void, Error> {
        if let current = call, current.invite.callID == callID { return current.prepare }
        guard call == nil, let invite = invites.removeValue(forKey: callID) else { throw PhoneError.serviceUnavailable }
        callshieldLog("CallKit is ringing; joining call room \(invite.room) silently")
        let prepare = Task<Void, Error> { @MainActor [weak self] in
            guard let self else { throw CancellationError() }
            try await self.join(invite)
        }
        call = LiveCall(invite: invite, prepare: prepare)
        return prepare
    }

    /// A silent join: no microphone and the engine held off, so the phone caller keeps hearing
    /// ringback. Publishing audio here would answer the phone call.
    private func join(_ invite: IncomingCallInvite) async throws {
        await stopLobby() // The lobby and a call room are never connected at the same time.
        await audioQueueDrained()
        guard call?.invite.callID == invite.callID else { throw CancellationError() }
        let room = Room()
        room.add(delegate: self)
        call?.room = room
        do {
            try await room.connect(url: serverURL, token: invite.token,
                                   connectOptions: ConnectOptions(autoSubscribe: true, enableMicrophone: false))
        } catch {
            guard call?.invite.callID == invite.callID else { throw error } // Ended while connecting: not a failure.
            callshieldLog("joining the call room failed: \(callshieldDetail(error))")
            throw CallConnectionError()
        }
        // Ended while connecting: closeCall() disconnects this room once this task has finished.
        guard call?.invite.callID == invite.callID else { throw CancellationError() }
        callshieldLog("joined call room")
        // People already in a room are not announced with participantDidConnect, so look.
        if await callerHasLeft(invite, from: room) { callEnded("the caller hung up before this phone joined") }
    }

    private func callerIsPresent(in room: Room, identity: String) -> Bool {
        room.remoteParticipants.values.contains { $0.identity?.stringValue == identity }
    }

    /// The SDK fills `remoteParticipants` from the join response in a task that `connect()` and a
    /// full reconnect do not wait for, so a caller who is not listed yet is looked for once more
    /// a moment later. A caller who really left ends the call one second later than it could.
    private func callerHasLeft(_ invite: IncomingCallInvite, from room: Room) async -> Bool {
        guard !callerIsPresent(in: room, identity: invite.callerIdentity) else { return false }
        try? await Task.sleep(nanoseconds: 1_000_000_000) // Returns early when closeCall() cancels this task.
        return call?.invite.callID == invite.callID && call?.room === room
            && !callerIsPresent(in: room, identity: invite.callerIdentity)
    }

    // MARK: - CallingBackend

    func start(callID: UUID, number: String) async throws {
        // LiveKit-rented numbers are inbound-only; outgoing calls stay with the system dialer.
        throw PhoneError.serviceUnavailable
    }

    func prepareIncoming(callID: UUID, number: String) async throws {
        try await preparation(for: callID).value
    }

    func answer(callID: UUID) async throws {
        try await preparation(for: callID).value // Waits for the silent join, starting it if needed.
        guard let current = call, current.invite.callID == callID, let room = current.room else { throw PhoneError.actionUnavailable }
        // The engine is still held off, so this publishes without capturing. Audio starts in activateAudio.
        do { try await room.localParticipant.setMicrophone(enabled: true) }
        catch {
            guard call?.invite.callID == callID else { throw PhoneError.actionUnavailable } // Ended meanwhile.
            callshieldLog("publishing the microphone failed: \(callshieldDetail(error))")
            throw CallConnectionError()
        }
        guard call?.invite.callID == callID else { throw PhoneError.actionUnavailable }
        call?.answered = true
        callshieldLog("answered: microphone published")
        announceConnectedIfReady()
    }

    func end(callID: UUID) async throws {
        invites[callID] = nil // Announced but never rung: CallKit refused it or another call was active.
        guard call?.invite.callID == callID else { connectLobbyIfNeeded(); return }
        closeCall()
        callshieldLog("ended by this phone")
    }

    func setMuted(_ muted: Bool, callID: UUID) async throws {
        guard let current = call, current.invite.callID == callID, current.answered, let room = current.room else {
            throw PhoneError.actionUnavailable
        }
        // On an existing publication this mutes or unmutes; it never unpublishes.
        try await room.localParticipant.setMicrophone(enabled: !muted)
    }

    func setHeld(_ held: Bool, callID: UUID) async throws { throw PhoneError.actionUnavailable }

    func sendDTMF(_ digits: String, callID: UUID) async throws {
        guard let current = call, current.invite.callID == callID, current.answered, let room = current.room,
              // The server silently drops keypad tones sent with a token that may not publish data.
              room.localParticipant.permissions.canPublishData else { throw PhoneError.actionUnavailable }
        for digit in digits {
            // RFC 4733 event codes, as in publishDtmf's documentation: 0-9, then * is 10 and # is 11.
            let code: UInt32
            switch digit {
            case "*": code = 10
            case "#": code = 11
            default:
                guard digit.isASCII, let value = digit.wholeNumberValue else { throw PhoneError.actionUnavailable }
                code = UInt32(value)
            }
            try await room.localParticipant.publishDtmf(code: code, digit: String(digit))
        }
    }

    func registerVoIPToken(_ token: Data?) async throws {} // No PushKit in this build.

    func activateAudio(_ session: AVAudioSession) {
        guard let callID = call?.invite.callID else { return }
        liveKitAudioQueue.async {
            do {
                // Only Simulator owns activation here; on iPhone CallKit owns it.
                // Same options as PhoneCallCoordinator.
                try session.setCategory(.playAndRecord, mode: .voiceChat, options: [.allowBluetoothHFP])
                #if targetEnvironment(simulator)
                try session.setActive(true)
                #endif
                try AudioManager.shared.setEngineAvailability(.default)
                Task { @MainActor in self.audioActivated(for: callID) }
            } catch {
                let detail = callshieldDetail(error)
                Task { @MainActor in self.audioFailed(for: callID, detail: detail) }
            }
        }
    }

    func deactivateAudio(_ session: AVAudioSession) {
        call?.audioActive = false
        liveKitAudioQueue.async {
            try? AudioManager.shared.setEngineAvailability(.none)
            #if targetEnvironment(simulator)
            try? AVAudioSession.sharedInstance().setActive(false, options: .notifyOthersOnDeactivation)
            #endif
        }
    }

    func reset() {
        invites.removeAll()
        if closeCall() != nil { callshieldLog("call reset") } else { connectLobbyIfNeeded() }
    }

    // MARK: - Call state

    private func audioActivated(for callID: UUID) {
        guard call?.invite.callID == callID else { return }
        call?.audioActive = true
        callshieldLog("audio activated")
        announceConnectedIfReady()
    }

    private func audioFailed(for callID: UUID, detail: String) {
        guard call?.invite.callID == callID else { return }
        callFailed("Audio could not start.", detail: detail)
    }

    /// `connected` means real media: the microphone is published and the engine is running
    /// inside CallKit's activation window. The two can finish in either order.
    private func announceConnectedIfReady() {
        guard let current = call, current.answered, current.audioActive, !current.connected else { return }
        call?.connected = true
        callshieldLog("connected")
        let now = Date()
        call?.connectedAt = now
        onEvent?(.connected(current.invite.callID, now))
        onEvent?(.deepfakeAssessment(current.invite.callID, DeepfakeAssessment(state: .waiting, updatedAt: now)))
        onEvent?(.transcriptAssessment(current.invite.callID, TranscriptAssessment(state: .listening, updatedAt: now)))
        startAssessmentWatchdog(callID: current.invite.callID)
    }

    /// The one place a call stops. Reaching it twice is harmless: a server teardown reports
    /// both the caller leaving and the room disconnecting, and the second finds no call.
    @discardableResult
    private func closeCall() -> LiveCall? {
        guard let closed = call else { return nil }
        call = nil
        assessmentWatchdog?.cancel(); assessmentWatchdog = nil
        closed.prepare.cancel()
        // CallKit sends didDeactivate only for a call whose audio it activated, so force the engine off.
        liveKitAudioQueue.async {
            try? AudioManager.shared.setEngineAvailability(.none)
            #if targetEnvironment(simulator)
            try? AVAudioSession.sharedInstance().setActive(false, options: .notifyOthersOnDeactivation)
            #endif
        }
        callTeardown = Task { @MainActor [weak self] in
            _ = await closed.prepare.result // join() has finished and cannot create a Room now.
            if let room = closed.room { await room.disconnect() }
            self?.connectLobbyIfNeeded()
        }
        return closed
    }

    private func callEnded(_ reason: String) {
        guard let closed = closeCall() else { return }
        callshieldLog("ended: \(reason)")
        onEvent?(.ended(closed.invite.callID, closed.connected ? .completed : .missed, Date()))
    }

    /// `message` is shown to the person on the call; `detail` is for the log only.
    private func callFailed(_ message: String, detail: String) {
        guard let closed = closeCall() else { return }
        callshieldLog("failed: \(message) (\(detail))")
        onEvent?(.failed(closed.invite.callID, message))
    }

    private func participantLeft(_ identity: String, in room: Room) {
        guard let current = call, current.room === room, current.invite.callerIdentity == identity else { return }
        callshieldLog("caller left")
        callEnded("the caller hung up")
    }

    private func roomDropped(_ room: Room, type: LiveKitErrorType, detail: String) {
        if room === lobbyRoom {
            lobbyRoom = nil
            callshieldLog("lobby dropped: \(detail)")
            // Two phones sharing the lobby token would otherwise keep pushing each other out.
            if type != .duplicateIdentity { scheduleLobbyRetry() }
            return
        }
        guard let current = call, current.room === room else { return }
        switch type {
        // The server closed it: the agent deleted the room, this phone was removed, or a reason
        // the SDK does not map (it reports "room closed" as unknown).
        case .roomDeleted, .participantRemoved, .serverShutdown, .duplicateIdentity, .unknown:
            callEnded("the call room closed (\(detail))")
        default:
            callFailed("The call was interrupted.", detail: detail)
        }
    }

    private func roomReconnected(_ room: Room) {
        guard let current = call, current.room === room else { return }
        let invite = current.invite
        Task { @MainActor in
            guard await self.callerHasLeft(invite, from: room) else { return }
            callshieldLog("caller left while this phone was reconnecting")
            self.callEnded("the caller hung up")
        }
    }

    // MARK: - Voice detector

    private func receiveAssessment(_ data: Data, in room: Room, isAgent: Bool) {
        guard var current = call, current.room === room, current.connected,
              room.connectionState == .connected else { return }
        let now = Date()
        let voice = DeepfakeUpdate.decode(data).flatMap {
            current.detector.receive($0, room: current.invite.room,
                callerIdentity: current.invite.callerIdentity, isAgent: isAgent, at: now)
        }
        let transcript = TranscriptUpdate.decode(data).flatMap {
            current.transcriptDetector.receive($0, room: current.invite.room,
                callerIdentity: current.invite.callerIdentity, isAgent: isAgent, at: now)
        }
        call = current
        if let voice { onEvent?(.deepfakeAssessment(current.invite.callID, voice)) }
        if let transcript { onEvent?(.transcriptAssessment(current.invite.callID, transcript)) }
    }

    private func startAssessmentWatchdog(callID: UUID) {
        assessmentWatchdog?.cancel()
        assessmentWatchdog = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                do { try await Task.sleep(nanoseconds: 2_000_000_000) } catch { return }
                guard let self, var current = self.call, current.invite.callID == callID,
                      let connectedAt = current.connectedAt else { return }
                let now = Date()
                let voice = current.detector.expire(at: now, connectedAt: connectedAt)
                let transcript = current.transcriptDetector.expire(at: now, connectedAt: connectedAt)
                self.call = current
                if let voice { self.onEvent?(.deepfakeAssessment(callID, voice)) }
                if let transcript { self.onEvent?(.transcriptAssessment(callID, transcript)) }
            }
        }
    }

    private func assessmentInterrupted(in room: Room) {
        guard let current = call, current.room === room, current.connected else { return }
        onEvent?(.deepfakeAssessment(current.invite.callID, DeepfakeAssessment(state: .unavailable, updatedAt: Date())))
        onEvent?(.transcriptAssessment(current.invite.callID, TranscriptAssessment(state: .unavailable, updatedAt: Date())))
    }

    // MARK: - RoomDelegate
    // Every requirement is `@objc optional`: a label that differs from the protocol compiles and
    // then never fires. The SDK calls these on its own queue, not the main one.

    nonisolated func room(_ room: Room, participant: RemoteParticipant?, didReceiveData data: Data,
                          forTopic topic: String, encryptionType: EncryptionType) { // RoomDelegate.swift:185
        if topic == IncomingCallInvite.topic {
            Task { @MainActor in self.receiveInvite(data, in: room) }
        } else if topic == DeepfakeUpdate.topic {
            // Participant kind is server-authenticated. SIP callers and ordinary clients
            // must never be able to supply their own voice verdicts.
            let isAgent = participant?.kind == .agent
            Task { @MainActor in self.receiveAssessment(data, in: room, isAgent: isAgent) }
        }
    }

    nonisolated func room(_ room: Room, participantDidDisconnect participant: RemoteParticipant) { // RoomDelegate.swift:102
        // Read now: the SDK wipes the participant as soon as this returns. It also sends this for
        // everyone while this phone disconnects or fully reconnects, which is not a hang-up.
        guard let identity = participant.identity?.stringValue, room.connectionState == .connected else { return }
        let isAgent = participant.kind == .agent
        Task { @MainActor in
            if isAgent { self.assessmentInterrupted(in: room) }
            self.participantLeft(identity, in: room)
        }
    }

    nonisolated func room(_ room: Room, didDisconnectWithError error: LiveKitError?) { // RoomDelegate.swift:78
        guard let error else { return } // nil is this phone's own disconnect().
        let type = error.type
        let detail = callshieldDetail(error)
        Task { @MainActor in self.roomDropped(room, type: type, detail: detail) }
    }

    nonisolated func room(_ room: Room, didStartReconnectWithMode reconnectMode: ReconnectMode) {
        Task { @MainActor in self.assessmentInterrupted(in: room) }
    }

    // Unlike roomDidReconnect, this also fires for a quick reconnect, which never leaves `.connected`.
    nonisolated func room(_ room: Room, didCompleteReconnectWithMode reconnectMode: ReconnectMode) { // RoomDelegate.swift:66
        // It fires when a reconnect fails too (Room+Engine.swift cleanUp), and then the room is
        // already disconnected: didDisconnectWithError handles that.
        guard room.connectionState == .connected else { return }
        Task { @MainActor in self.roomReconnected(room) }
    }
}

import AVFAudio
import CallKit
import Foundation
import PushKit

@MainActor
final class PhoneCallCoordinator: NSObject, CXProviderDelegate, PKPushRegistryDelegate {
    let backend: CallingBackend
    private let microphonePermission: @MainActor () async -> Bool
    private let provider: CXProvider
    private let controller = CXCallController()
    private var registry: PKPushRegistry?
    private var session = PhoneSessionState()
    var onCallChanged: ((PhoneCall?) -> Void)?
    var onRecord: ((PhoneCallRecord) -> Void)?
    var onError: ((String) -> Void)?
    var active: PhoneCall? { session.current }

    init(backend: CallingBackend, microphonePermission: @escaping @MainActor () async -> Bool = {
        await withCheckedContinuation { continuation in
            AVAudioSession.sharedInstance().requestRecordPermission { continuation.resume(returning: $0) }
        }
    }) {
        self.backend = backend
        self.microphonePermission = microphonePermission
        let configuration = CXProviderConfiguration()
        configuration.supportedHandleTypes = [.phoneNumber, .generic]
        configuration.supportsVideo = false
        configuration.maximumCallGroups = 1
        configuration.maximumCallsPerCallGroup = 1
        configuration.includesCallsInRecents = true
        provider = CXProvider(configuration: configuration)
        super.init()
        provider.setDelegate(self, queue: .main)
        backend.onEvent = { [weak self] event in self?.receive(event) }
    }

    func registerIncomingCallsIfConfigured() {
        guard backend.isConfigured else { return }
        backend.listenForIncomingCalls()
        // PushKit needs the push entitlement. A backend that rings through `incoming` events gets no registry.
        guard backend.usesVoIPPush, registry == nil else { return }
        let registry = PKPushRegistry(queue: .main)
        registry.delegate = self
        registry.desiredPushTypes = [.voIP]
        self.registry = registry
    }

    func start(_ person: Person) async throws {
        guard backend.isConfigured else { throw PhoneError.serviceUnavailable }
        guard active == nil else { throw PhoneError.actionUnavailable }
        let permitted = await microphonePermission()
        guard permitted else { throw PhoneError.microphoneDenied }
        let number = try PhoneNumber.normalized(person.number)
        let call = PhoneCall(id: UUID(), person: person, direction: .outgoing, createdAt: Date(), stage: .connecting)
        guard session.begin(call) else { throw PhoneError.actionUnavailable }
        changed()
        let action = CXStartCallAction(call: call.id, handle: CXHandle(type: .phoneNumber, value: number))
        do { try await request(action) }
        catch { finish(call.id, outcome: .failed, reason: .failed); throw error }
    }

    func answer() async throws {
        guard let call = active, call.stage == .incoming else { throw PhoneError.actionUnavailable }
        try await request(CXAnswerCallAction(call: call.id))
    }
    func end() async throws {
        guard let id = active?.id else { return }
        try await request(CXEndCallAction(call: id))
    }
    func setMuted(_ value: Bool) async throws {
        guard let id = active?.id else { throw PhoneError.actionUnavailable }
        try await request(CXSetMutedCallAction(call: id, muted: value))
    }
    func setHeld(_ value: Bool) async throws {
        guard let id = active?.id, active?.connectedAt != nil else { throw PhoneError.actionUnavailable }
        try await request(CXSetHeldCallAction(call: id, onHold: value))
    }
    func sendDTMF(_ digits: String) async throws {
        guard let id = active?.id, active?.connectedAt != nil, !digits.isEmpty,
              digits.allSatisfy({ "0123456789*#".contains($0) }) else { throw PhoneError.actionUnavailable }
        try await request(CXPlayDTMFCallAction(call: id, digits: digits, type: .singleTone))
    }
    func setSpeaker(_ value: Bool) throws {
        guard let id = active?.id, active?.connectedAt != nil else { throw PhoneError.actionUnavailable }
        try AVAudioSession.sharedInstance().overrideOutputAudioPort(value ? .speaker : .none)
        session.setSpeaker(value, id: id)
        changed()
    }

    private func request(_ action: CXAction) async throws {
        #if targetEnvironment(simulator)
        // Simulator has no system call UI/audio activation. Use the same real backend
        // through the app controls; only physical devices submit CallKit transactions.
        guard let action = action as? CXCallAction, let call = active, call.id == action.callUUID else {
            throw PhoneError.actionUnavailable
        }
        switch action {
        case is CXAnswerCallAction:
            let allowed = await microphonePermission()
            guard active?.id == call.id else { throw PhoneError.actionUnavailable }
            do {
                guard allowed else { throw PhoneError.microphoneDenied }
                session.connecting(id: call.id)
                changed()
                try await backend.answer(callID: call.id)
                guard active?.id == call.id else { return }
                backend.activateAudio(AVAudioSession.sharedInstance())
            } catch {
                guard active?.id == call.id else { throw error }
                backend.reset()
                finish(call.id, outcome: .failed, reason: .failed)
                throw error
            }
        case is CXEndCallAction:
            do { try await backend.end(callID: call.id) }
            catch { backend.reset(); finish(call.id, outcome: .failed, reason: .failed); throw error }
            finish(call.id, outcome: call.connectedAt == nil ? (call.direction == .incoming ? .missed : .cancelled) : .completed,
                   reason: .remoteEnded)
        case let mute as CXSetMutedCallAction:
            try await backend.setMuted(mute.isMuted, callID: call.id)
            guard active?.id == call.id else { return }
            session.setMuted(mute.isMuted, id: call.id)
            changed()
        default: throw PhoneError.actionUnavailable
        }
        #else
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            controller.request(CXTransaction(action: action)) { error in
                if let error { continuation.resume(throwing: error) }
                else { continuation.resume() }
            }
        }
        #endif
    }

    private func changed() { onCallChanged?(active) }
    private func finish(_ id: UUID, outcome: PhoneCallOutcome, reason: CXCallEndedReason, at date: Date = Date()) {
        guard let record = session.finish(id: id, outcome: outcome, at: date) else { return }
        #if targetEnvironment(simulator)
        backend.deactivateAudio(AVAudioSession.sharedInstance())
        #else
        provider.reportCall(with: id, endedAt: date, reason: reason)
        #endif
        changed()
        onRecord?(record)
    }

    private func receive(_ event: CallingEvent) {
        switch event {
        case .connected(let id, let date):
            guard active?.id == id else { return }
            session.connected(id: id, at: date)
            #if !targetEnvironment(simulator)
            if active?.direction == .outgoing { provider.reportOutgoingCall(with: id, connectedAt: date) }
            #endif
            changed()
        case .ended(let id, let outcome, let date):
            finish(id, outcome: outcome, reason: outcome == .missed ? .unanswered : .remoteEnded, at: date)
        case .assessmentStarted(let id): session.assess(id: id, voice: .analyzing); changed()
        case .assessed(let id, let voice):
            guard voice != .analyzing else { return }
            session.assess(id: id, voice: voice); changed()
        case .deepfakeAssessment(let id, let assessment):
            session.assessDeepfake(id: id, assessment: assessment); changed()
        case .transcriptAssessment(let id, let assessment):
            session.assessTranscript(id: id, assessment: assessment); changed()
        case .failed(let id, let message):
            guard active?.id == id else { return }
            backend.reset()
            finish(id, outcome: .failed, reason: .failed)
            onError?(message)
        case .incoming(let id, let handle, let name): reportIncoming(id, handle: handle, name: name)
        case .incomingCallsUnavailable(let message): onError?(message)
        }
    }

    /// A backend that rings without PushKit announced a call while the app is open.
    private func reportIncoming(_ id: UUID, handle: String, name: String?) {
        // `end` for a call that never rang only makes the backend forget it.
        guard active == nil else { Task { @MainActor in try? await self.backend.end(callID: id) }; return }
        let number = try? PhoneNumber.normalized(handle)
        let name = name.map { String($0.prefix(128)) }
        let update = CXCallUpdate()
        // A withheld or non-numeric caller ID still rings, under a neutral label.
        update.remoteHandle = number.map { CXHandle(type: .phoneNumber, value: $0) } ?? CXHandle(type: .generic, value: "Unknown caller")
        update.localizedCallerName = name
        update.supportsHolding = false
        // The call-room token cannot publish data, and the server drops keypad tones without that grant.
        update.supportsDTMF = false
        update.supportsGrouping = false
        update.supportsUngrouping = false
        let person = number.map { PhoneNumber.person($0, name: name) }
            ?? Person(name: name ?? "Unknown caller", number: "", initials: "?", color: .slate, voice: .unknown)
        #if targetEnvironment(simulator)
        guard session.begin(PhoneCall(id: id, person: person, direction: .incoming,
                                     createdAt: Date(), stage: .incoming)) else { return }
        print("[Callshield] Simulator incoming call; use Accept in the app")
        changed()
        Task { @MainActor in
            do { try await self.backend.prepareIncoming(callID: id, number: number ?? "") }
            catch {
                guard self.active?.id == id else { return }
                self.backend.reset()
                self.finish(id, outcome: .failed, reason: .failed)
                self.onError?(error.localizedDescription)
            }
        }
        #else
        provider.reportNewIncomingCall(with: id, update: update) { error in
            Task { @MainActor in
                // CallKit can refuse (Do Not Disturb, a blocked caller). Then nothing rang and there is no session.
                if let error {
                    print("[Callshield] CallKit refused the incoming call: \(error.localizedDescription)")
                    try? await self.backend.end(callID: id)
                    return
                }
                guard self.session.begin(PhoneCall(id: id, person: person, direction: .incoming,
                                                   createdAt: Date(), stage: .incoming)) else {
                    self.provider.reportCall(with: id, endedAt: Date(), reason: .failed)
                    try? await self.backend.end(callID: id)
                    return
                }
                print("[Callshield] CallKit reported the incoming call")
                self.changed()
                Task { @MainActor in
                    do { try await self.backend.prepareIncoming(callID: id, number: number ?? "") }
                    catch {
                        guard self.active?.id == id else { return }
                        self.backend.reset()
                        self.finish(id, outcome: .failed, reason: .failed)
                        self.onError?(error.localizedDescription)
                    }
                }
            }
        }
        #endif
    }

    nonisolated func providerDidReset(_ provider: CXProvider) {
        Task { @MainActor in
            self.backend.reset()
            if let id = self.active?.id { self.finish(id, outcome: .failed, reason: .failed) }
        }
    }

    nonisolated func provider(_ provider: CXProvider, perform action: CXStartCallAction) {
        Task { @MainActor in
            guard self.active?.id == action.callUUID else { action.fail(); return }
            do {
                try AVAudioSession.sharedInstance().setCategory(.playAndRecord, mode: .voiceChat, options: [.allowBluetoothHFP])
                provider.reportOutgoingCall(with: action.callUUID, startedConnectingAt: Date())
                try await self.backend.start(callID: action.callUUID, number: action.handle.value)
                guard self.active?.id == action.callUUID else { action.fail(); return }
                action.fulfill()
                let update = CXCallUpdate()
                update.localizedCallerName = self.active?.person.name
                update.remoteHandle = action.handle
                update.supportsHolding = true
                update.supportsDTMF = true
                update.supportsGrouping = false
                update.supportsUngrouping = false
                provider.reportCall(with: action.callUUID, updated: update)
            } catch {
                action.fail()
                guard self.active?.id == action.callUUID else { return }
                self.backend.reset()
                self.finish(action.callUUID, outcome: .failed, reason: .failed)
                self.onError?(error.localizedDescription)
            }
        }
    }

    nonisolated func provider(_ provider: CXProvider, perform action: CXAnswerCallAction) {
        Task { @MainActor in
            guard self.active?.id == action.callUUID else { action.fail(); return }
            let allowed = await self.microphonePermission()
            guard allowed else {
                action.fail()
                self.backend.reset() // The backend may already have joined the call silently.
                self.finish(action.callUUID, outcome: .failed, reason: .failed)
                self.onError?(PhoneError.microphoneDenied.localizedDescription)
                return
            }
            guard self.active?.id == action.callUUID else { action.fail(); return }
            self.session.connecting(id: action.callUUID)
            self.changed()
            do {
                try AVAudioSession.sharedInstance().setCategory(.playAndRecord, mode: .voiceChat, options: [.allowBluetoothHFP])
                try await self.backend.answer(callID: action.callUUID)
                guard self.active?.id == action.callUUID else { action.fail(); return }
                action.fulfill()
                // The backend's connected event, not answering alone, starts the duration/analysis.
            } catch {
                action.fail()
                guard self.active?.id == action.callUUID else { return }
                self.backend.reset()
                self.finish(action.callUUID, outcome: .failed, reason: .failed)
                self.onError?(error.localizedDescription)
            }
        }
    }

    nonisolated func provider(_ provider: CXProvider, perform action: CXEndCallAction) {
        Task { @MainActor in
            guard let call = self.active, call.id == action.callUUID else { action.fulfill(); return }
            do { try await self.backend.end(callID: action.callUUID) }
            catch { self.backend.reset(); self.onError?(error.localizedDescription) }
            self.finish(action.callUUID, outcome: call.connectedAt == nil ? (call.direction == .incoming ? .missed : .cancelled) : .completed, reason: .remoteEnded)
            action.fulfill()
        }
    }

    nonisolated func provider(_ provider: CXProvider, perform action: CXSetMutedCallAction) {
        Task { @MainActor in
            guard self.active?.id == action.callUUID else { action.fail(); return }
            do {
                try await self.backend.setMuted(action.isMuted, callID: action.callUUID)
                guard self.active?.id == action.callUUID else { action.fail(); return }
                self.session.setMuted(action.isMuted, id: action.callUUID)
                self.changed(); action.fulfill()
            } catch { action.fail(); self.onError?(error.localizedDescription) }
        }
    }
    nonisolated func provider(_ provider: CXProvider, perform action: CXSetHeldCallAction) {
        Task { @MainActor in
            guard self.active?.id == action.callUUID else { action.fail(); return }
            do {
                try await self.backend.setHeld(action.isOnHold, callID: action.callUUID)
                guard self.active?.id == action.callUUID else { action.fail(); return }
                self.session.setHeld(action.isOnHold, id: action.callUUID)
                self.changed(); action.fulfill()
            } catch { action.fail(); self.onError?(error.localizedDescription) }
        }
    }
    nonisolated func provider(_ provider: CXProvider, perform action: CXPlayDTMFCallAction) {
        Task { @MainActor in
            guard self.active?.id == action.callUUID else { action.fail(); return }
            do { try await self.backend.sendDTMF(action.digits, callID: action.callUUID); action.fulfill() }
            catch { action.fail(); self.onError?(error.localizedDescription) }
        }
    }
    nonisolated func provider(_ provider: CXProvider, timedOutPerforming action: CXAction) {
        Task { @MainActor in
            guard let action = action as? CXCallAction, self.active?.id == action.callUUID else { return }
            self.backend.reset()
            self.finish(action.callUUID, outcome: .failed, reason: .failed)
        }
    }
    nonisolated func provider(_ provider: CXProvider, didActivate audioSession: AVAudioSession) {
        Task { @MainActor in self.backend.activateAudio(audioSession) }
    }
    nonisolated func provider(_ provider: CXProvider, didDeactivate audioSession: AVAudioSession) {
        Task { @MainActor in self.backend.deactivateAudio(audioSession) }
    }

    nonisolated func pushRegistry(_ registry: PKPushRegistry, didUpdate pushCredentials: PKPushCredentials, for type: PKPushType) {
        guard type == .voIP else { return }
        Task { @MainActor in
            do { try await self.backend.registerVoIPToken(pushCredentials.token) }
            catch { self.onError?(error.localizedDescription) }
        }
    }
    nonisolated func pushRegistry(_ registry: PKPushRegistry, didInvalidatePushTokenFor type: PKPushType) {
        guard type == .voIP else { return }
        Task { @MainActor in
            do { try await self.backend.registerVoIPToken(nil) }
            catch { self.onError?(error.localizedDescription) }
        }
    }
    nonisolated func pushRegistry(_ registry: PKPushRegistry, didReceiveIncomingPushWith payload: PKPushPayload,
                                 for type: PKPushType, completion: @escaping () -> Void) {
        guard type == .voIP else { completion(); return }
        let dictionary = payload.dictionaryPayload
        let parsedID = (dictionary["callUUID"] as? String).flatMap(UUID.init(uuidString:))
        let number = (dictionary["handle"] as? String).flatMap { try? PhoneNumber.normalized($0) }
        let name = (dictionary["callerName"] as? String).map { String($0.prefix(128)) }
        Task { @MainActor in
            // Report immediately, before any backend work. Even malformed VoIP pushes must
            // satisfy Apple's CallKit reporting obligation, then end the rejected call.
            let id = parsedID ?? UUID()
            let update = CXCallUpdate()
            update.remoteHandle = CXHandle(type: .phoneNumber, value: number ?? "Unknown")
            update.localizedCallerName = name
            update.supportsHolding = true
            update.supportsDTMF = true
            update.supportsGrouping = false
            update.supportsUngrouping = false
            defer { completion() }
            do { try await self.provider.reportNewIncomingCall(with: id, update: update) }
            catch { return }
            guard parsedID != nil, let number, self.backend.isConfigured,
                  self.session.begin(PhoneCall(id: id, person: PhoneNumber.person(number, name: name),
                                              direction: .incoming, createdAt: Date(), stage: .incoming)) else {
                self.provider.reportCall(with: id, endedAt: Date(), reason: .failed)
                return
            }
            self.changed()
            Task { @MainActor in
                do { try await self.backend.prepareIncoming(callID: id, number: number) }
                catch {
                    guard self.active?.id == id else { return }
                    self.backend.reset()
                    self.finish(id, outcome: .failed, reason: .failed)
                    self.onError?(error.localizedDescription)
                }
            }
        }
    }
}

import Foundation

enum PhoneTab: String, CaseIterable {
    case favorites = "Favorites", recents = "Recents", contacts = "Contacts", keypad = "Keypad", settings = "Settings"
    var symbol: String {
        switch self {
        case .favorites: return "star"
        case .recents: return "clock"
        case .contacts: return "person.2"
        case .keypad: return "circle.grid.3x3"
        case .settings: return "gearshape"
        }
    }
}

enum CallDirection: String, Codable { case incoming, outgoing }
enum PhoneCallOutcome: String, Codable { case completed, missed, cancelled, failed, answeredElsewhere }

struct PhoneCallRecord: Identifiable, Codable, Equatable {
    let id: UUID
    let person: Person
    let date: Date
    let duration: Int
    let direction: CallDirection
    let outcome: PhoneCallOutcome
    let voice: Voice
    var deepfake: DeepfakeAssessment? = nil
    var transcript: TranscriptAssessment? = nil
}

struct PhoneCall: Identifiable, Equatable {
    enum Stage: String { case incoming, connecting, connected, held }
    let id: UUID
    let person: Person
    let direction: CallDirection
    let createdAt: Date
    var connectedAt: Date?
    var stage: Stage
    var voice: Voice = .unknown
    var muted = false
    var speaker = false
    var deepfake: DeepfakeAssessment? = nil
    var transcript: TranscriptAssessment? = nil
    var lastDeepfakeResult: DeepfakeAssessment? = nil
    var lastTranscriptResult: TranscriptAssessment? = nil
}

struct PhoneSnapshot: Codable {
    var history: [PhoneCallRecord] = []
    var favorites: [Person] = []
    var largeText = false
    var hiddenHistoryIDs: Set<UUID> = []
}

enum PhoneError: LocalizedError {
    case invalidNumber, serviceUnavailable, simulatorUnavailable, microphoneDenied, actionUnavailable
    var errorDescription: String? {
        switch self {
        case .invalidNumber: return "Enter a valid phone number."
        case .serviceUnavailable: return "Calling through Callshield isn’t available yet. You can call using your mobile service."
        case .simulatorUnavailable: return "Phone calls require an iPhone. They aren’t available in the simulator."
        case .microphoneDenied: return "Allow microphone access in Settings to make a Callshield call."
        case .actionUnavailable: return "That action isn’t available for this call."
        }
    }
}

enum PhoneNumber {
    /// Accept a phone number, not arbitrary URI input; never allow a callback URL to recurse.
    static func normalized(_ text: String) throws -> String {
        let allowed = CharacterSet(charactersIn: "+0123456789*# ()-.\u{00A0}")
        guard !text.isEmpty, text.count <= 64,
              text.unicodeScalars.allSatisfy({ allowed.contains($0) }) else { throw PhoneError.invalidNumber }
        let number = text.filter { "+0123456789*#".contains($0) }
        guard number.contains(where: { "0123456789".contains($0) }),
              number.count <= 32, number.filter({ $0 == "+" }).count <= 1,
              !number.dropFirst().contains("+") else { throw PhoneError.invalidNumber }
        return number
    }

    static func fromURL(_ url: URL) throws -> String {
        guard url.scheme?.lowercased() == "tel", url.host == nil, url.query == nil, url.fragment == nil,
              let components = URLComponents(url: url, resolvingAgainstBaseURL: false) else { throw PhoneError.invalidNumber }
        return try normalized(components.path)
    }

    static func person(_ number: String, name: String? = nil) -> Person {
        let name = name?.trimmingCharacters(in: .whitespacesAndNewlines)
        let display = name?.isEmpty == false ? name! : number
        let initials = name?.isEmpty == false ? name!.split(separator: " ").prefix(2).compactMap(\.first).map(String.init).joined() : "?"
        return Person(name: display, number: number, initials: initials, color: .slate, voice: .unknown)
    }
}

import Foundation

protocol PhoneRepository {
    func load() throws -> PhoneSnapshot
    func save(_ snapshot: PhoneSnapshot) throws
}

struct LocalPhoneRepository: PhoneRepository {
    let url: URL
    init(url: URL? = nil) {
        self.url = url ?? FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("Callshield", isDirectory: true).appendingPathComponent("phone-v1.json")
    }
    func load() throws -> PhoneSnapshot {
        guard FileManager.default.fileExists(atPath: url.path) else { return PhoneSnapshot() }
        return try JSONDecoder().decode(PhoneSnapshot.self, from: Data(contentsOf: url))
    }
    func save(_ snapshot: PhoneSnapshot) throws {
        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
        var bounded = snapshot
        bounded.history = Array(snapshot.history.prefix(1000))
        var directory = url.deletingLastPathComponent()
        var values = URLResourceValues()
        values.isExcludedFromBackup = true
        try directory.setResourceValues(values)
        let data = try JSONEncoder().encode(bounded)
        try data.write(to: url, options: [.atomic, .completeFileProtectionUntilFirstUserAuthentication])
    }
}

import Foundation

/// Independent of CallKit so service-event ordering can be verified without making calls.
struct PhoneSessionState {
    private(set) var current: PhoneCall?

    mutating func begin(_ call: PhoneCall) -> Bool {
        guard current == nil else { return false }
        current = call
        return true
    }
    mutating func connected(id: UUID, at date: Date) {
        guard current?.id == id, current?.connectedAt == nil else { return }
        current?.connectedAt = date
        current?.stage = .connected
    }
    mutating func connecting(id: UUID) {
        guard current?.id == id, current?.stage == .incoming else { return }
        current?.stage = .connecting
    }
    mutating func assess(id: UUID, voice: Voice) {
        guard current?.id == id, current?.connectedAt != nil else { return }
        current?.voice = voice
    }
    mutating func assessDeepfake(id: UUID, assessment: DeepfakeAssessment) {
        guard current?.id == id, current?.connectedAt != nil else { return }
        current?.deepfake = assessment
        current?.voice = assessment.voice
        if [.ai, .human, .uncertain].contains(assessment.state) {
            current?.lastDeepfakeResult = assessment
        }
    }
    mutating func assessTranscript(id: UUID, assessment: TranscriptAssessment) {
        guard current?.id == id, current?.connectedAt != nil else { return }
        current?.transcript = assessment
        if assessment.state == .monitoring { current?.lastTranscriptResult = assessment }
    }
    mutating func setMuted(_ muted: Bool, id: UUID) {
        guard current?.id == id else { return }
        current?.muted = muted
    }
    mutating func setSpeaker(_ speaker: Bool, id: UUID) {
        guard current?.id == id else { return }
        current?.speaker = speaker
    }
    mutating func setHeld(_ held: Bool, id: UUID) {
        guard current?.id == id, current?.connectedAt != nil else { return }
        current?.stage = held ? .held : .connected
    }
    mutating func finish(id: UUID, outcome: PhoneCallOutcome, at date: Date) -> PhoneCallRecord? {
        guard let call = current, call.id == id else { return nil }
        current = nil
        let assessment = call.lastDeepfakeResult ?? call.deepfake
        let voice = assessment?.voice ?? call.voice
        return PhoneCallRecord(id: call.id, person: call.person, date: call.createdAt,
                               duration: call.connectedAt.map { max(0, Int(date.timeIntervalSince($0))) } ?? 0,
                               direction: call.direction, outcome: outcome,
                               voice: call.connectedAt == nil || voice == .analyzing ? .unknown : voice,
                               deepfake: call.connectedAt == nil ? nil : assessment,
                               transcript: call.connectedAt == nil ? nil : (call.lastTranscriptResult ?? call.transcript))
    }
}

import SwiftUI

struct ProductionCallView: View {
    let call: PhoneCall
    @EnvironmentObject private var store: ProductionStore
    @State private var showingKeypad = false
    @State private var busy = false
    private let clock = Timer.publish(every: 1, on: .main, in: .common).autoconnect()
    @State private var now = Date()
    /// A service that cannot hold a call or send keypad tones (LiveKit) does not get buttons that can only fail.
    @MainActor private var offersHoldAndKeypad: Bool { store.coordinator.backend.supportsHoldAndKeypad }
    var body: some View {
        GeometryReader { geometry in
            ScrollView {
                VStack(spacing: 18) {
                    Label("Callshield", systemImage: "checkmark.shield").font(.subheadline).foregroundStyle(Color(hex: 0xD3DFD7))
                    #if targetEnvironment(simulator)
                    Text("Simulator call test").font(.caption).foregroundStyle(Color(hex: 0xD3DFD7))
                    #endif
                    Avatar(person: call.person, size: 80).padding(.top, 12)
                    Text(call.person.name).font(.title.weight(.medium))
                    Text(call.person.number).font(.subheadline).foregroundStyle(Color(hex: 0xBDCCC3))
                    Text(status).monospacedDigit().foregroundStyle(Color(hex: 0x9FB5A8))
                    if call.connectedAt != nil {
                        VStack(spacing: 10) {
                            Text("Voice / deepfake analysis").font(.caption.weight(.semibold))
                            VoiceBadge(voice: call.voice, size: 13, onCall: true)
                            Text(assessment).font(.caption).foregroundStyle(Color(hex: 0xD0DCD5))
                            if let previous = call.lastDeepfakeResult,
                               let current = call.deepfake, [.waiting, .analyzing, .unavailable].contains(current.state) {
                                Text("Last result: \(previous.voice.label)").font(.caption.weight(.semibold))
                            }
                            Text("Not an identity check").font(.caption2).foregroundStyle(Color(hex: 0x8DA597))
                        }.padding(16).frame(maxWidth: .infinity)
                            .background(.white.opacity(0.05), in: RoundedRectangle(cornerRadius: 18))
                    }
                    if call.connectedAt != nil {
                        let text = call.transcript ?? TranscriptAssessment(state: .listening, updatedAt: now)
                        VStack(spacing: 8) {
                            Label("Transcript analysis", systemImage: "text.bubble").font(.caption.weight(.semibold))
                            Text(text.title).font(.subheadline.weight(.semibold))
                                .foregroundStyle(text.isWarning ? Color(hex: 0xFFD59A) : Color.white)
                                .accessibilityIdentifier("transcriptAssessmentTitle")
                            Text(text.message).font(.caption).foregroundStyle(Color(hex: 0xD0DCD5))
                                .accessibilityIdentifier("transcriptAssessmentScore")
                            Text("Based on the caller’s words. A low score does not prove a call is safe.")
                                .font(.caption2).foregroundStyle(Color(hex: 0x8DA597))
                        }.padding(16).frame(maxWidth: .infinity)
                            .background(.white.opacity(0.05), in: RoundedRectangle(cornerRadius: 18))
                    }
                    Spacer(minLength: 20)
                    if call.stage == .incoming {
                        HStack {
                            action("Decline", "phone.down.fill", color: Color(hex: 0xF44E54)) { try await store.coordinator.end() }
                            Spacer()
                            action("Accept", "phone.fill", color: Color(hex: 0x32C968)) { try await store.coordinator.answer() }
                        }.padding(.horizontal, 12)
                    } else {
                        if showingKeypad {
                            PhoneKeypad { digit in perform { try await store.coordinator.sendDTMF(digit) } }
                        } else {
                            HStack(spacing: 24) {
                                action(call.muted ? "unmute" : "mute", call.muted ? "mic.slash" : "mic", selected: call.muted) {
                                    try await store.coordinator.setMuted(!call.muted)
                                }
                                action("speaker", "speaker.wave.2", selected: call.speaker) {
                                    try store.coordinator.setSpeaker(!call.speaker)
                                }
                                if offersHoldAndKeypad {
                                    action(call.stage == .held ? "resume" : "hold", "pause", selected: call.stage == .held) {
                                        try await store.coordinator.setHeld(call.stage != .held)
                                    }
                                }
                            }.disabled(call.connectedAt == nil)
                        }
                        if offersHoldAndKeypad {
                            Button(showingKeypad ? "Hide keypad" : "Keypad") { showingKeypad.toggle() }
                                .disabled(call.connectedAt == nil).padding(8)
                        }
                        action("End call", "phone.down.fill", color: Color(hex: 0xF44E54)) { try await store.coordinator.end() }
                    }
                }
                .padding(28).frame(maxWidth: 500).frame(minHeight: geometry.size.height).frame(maxWidth: .infinity)
            }.scrollIndicators(.hidden)
        }
        .multilineTextAlignment(.center).foregroundStyle(.white)
        .background(RadialGradient(colors: [Color(hex: 0x3A554C), Color(hex: 0x25382F), Color(hex: 0x131F1C)], center: .topLeading, startRadius: 0, endRadius: 700).ignoresSafeArea())
        .onReceive(clock) { now = $0 }
    }
    private var status: String {
        switch call.stage {
        case .incoming: return "Incoming call"
        case .connecting: return "Connecting…"
        case .held: return "On hold"
        case .connected: return callDuration(call.connectedAt.map { max(0, Int(now.timeIntervalSince($0))) } ?? 0)
        }
    }
    private var assessment: String {
        if let deepfake = call.deepfake { return deepfake.message }
        switch call.voice {
        case .analyzing: return "Checking the caller’s voice…"
        case .ai: return "This voice may be AI-generated."
        case .human: return "This voice appears to be human."
        case .unknown: return "A voice assessment is not available."
        }
    }
    private func action(_ title: String, _ symbol: String, color: Color = .white.opacity(0.13), selected: Bool = false,
                        operation: @escaping () async throws -> Void) -> some View {
        Button { perform(operation) } label: {
            VStack(spacing: 9) {
                Image(systemName: symbol).font(.system(size: 27))
                    .foregroundStyle(selected ? Color(hex: 0x273C31) : .white)
                    .frame(width: 64, height: 64).background(selected ? .white : color, in: Circle())
                Text(title).font(.caption)
            }
        }.buttonStyle(.plain).disabled(busy).accessibilityValue(selected ? "On" : "Off")
    }
    private func perform(_ operation: @escaping () async throws -> Void) {
        guard !busy else { return }
        busy = true
        Task {
            defer { busy = false }
            do { try await operation() }
            catch { store.errorMessage = error.localizedDescription }
        }
    }
}

