struct VoicemailPlaybackView: View {
    let message: VoicemailMessage
    @EnvironmentObject private var store: ProductionStore
    @Environment(\.dismiss) private var dismiss
    @Environment(\.scenePhase) private var scenePhase
    @State private var player: AVPlayer?
    @State private var playing = false
    @State private var busy = false
    @State private var presented = true
    @State private var allowsPlayback = true
    @State private var error: String?
    @State private var endObserver: NSObjectProtocol?
    @State private var failureObserver: NSObjectProtocol?
    var body: some View {
        NavigationStack {
            VStack(spacing: 20) {
                Avatar(person: message.caller, size: 80)
                Text(message.caller.name).font(.title2.weight(.semibold))
                Text(message.date.formatted()).foregroundStyle(.secondary)
                Text(callDuration(message.duration)).monospacedDigit()
                Button {
                    Task { await togglePlayback() }
                } label: { Label(playing ? "Pause" : "Play", systemImage: playing ? "pause.fill" : "play.fill") }
                .buttonStyle(.borderedProminent).disabled(busy)
                if let error { Text(error).font(.caption).foregroundStyle(.secondary) }
                Spacer()
            }.padding(24)
            .toolbar { ToolbarItem(placement: .confirmationAction) { Button("Done") { dismiss() } } }
            .onDisappear { presented = false; stopPlayback() }
            .onChange(of: scenePhase) { phase in
                allowsPlayback = phase == .active
                if phase != .active { player?.pause(); playing = false }
            }
        }.tint(Palette.green)
    }
    @MainActor private func togglePlayback() async {
        guard !busy else { return }
        if playing { player?.pause(); playing = false; return }
        busy = true
        defer { busy = false }
        do {
            // Backend returns a short-lived, authenticated HTTPS media URL. There is
            // no microphone recording, local sample media, or cellular voicemail API.
            guard message.audioURL.scheme?.lowercased() == "https" else { throw PhoneError.actionUnavailable }
            try await store.markVoicemailRead(message)
            guard presented, allowsPlayback, store.active == nil else { return }
            if player == nil {
                try AVAudioSession.sharedInstance().setCategory(.playback, mode: .spokenAudio)
                try AVAudioSession.sharedInstance().setActive(true)
                let item = AVPlayerItem(url: message.audioURL)
                player = AVPlayer(playerItem: item)
                endObserver = NotificationCenter.default.addObserver(forName: .AVPlayerItemDidPlayToEndTime, object: item, queue: .main) { _ in
                    Task { @MainActor in playing = false; player?.seek(to: .zero) }
                }
                failureObserver = NotificationCenter.default.addObserver(forName: .AVPlayerItemFailedToPlayToEndTime, object: item, queue: .main) { _ in
                    Task { @MainActor in playing = false; error = "This voicemail couldn’t be played. Please try again." }
                }
            }
            player?.play(); playing = true; error = nil
        } catch { self.error = error.localizedDescription }
    }
    private func stopPlayback() {
        player?.pause(); player = nil; playing = false
        if let endObserver { NotificationCenter.default.removeObserver(endObserver) }
        if let failureObserver { NotificationCenter.default.removeObserver(failureObserver) }
        endObserver = nil; failureObserver = nil
        // Do not deactivate audio if CallKit has already activated a new call.
        if store.active == nil { try? AVAudioSession.sharedInstance().setActive(false, options: .notifyOthersOnDeactivation) }
    }
}

import Foundation
import LiveCommunicationKit
import UIKit

@MainActor
protocol SystemPhoneService {
    func dial(_ number: String) async throws
    func recentCalls() async throws -> [PhoneCallRecord]
}

@MainActor
final class AppleSystemPhoneService: SystemPhoneService {
    private let usesDefaultDialer: Bool
    init(usesDefaultDialer: Bool = AppConfiguration.defaultDialerEnabled) { self.usesDefaultDialer = usesDefaultDialer }

    func dial(_ number: String) async throws {
        let number = try PhoneNumber.normalized(number)
        #if targetEnvironment(simulator)
        throw PhoneError.simulatorUnavailable
        #else
        if #available(iOS 26, *), usesDefaultDialer {
            let handle = Handle(type: .phoneNumber, value: number)
            try await TelephonyConversationManager.sharedInstance.startCellularConversation(
                StartCellularConversationAction(handle, cellularService: nil))
            return
        }
        var components = URLComponents()
        if #available(iOS 18.2, *) { components.scheme = "telephony" }
        else { components.scheme = "tel" }
        components.path = number
        guard let url = components.url else { throw PhoneError.invalidNumber }
        let opened = await UIApplication.shared.open(url)
        guard opened else { throw PhoneError.actionUnavailable }
        #endif
    }

    func recentCalls() async throws -> [PhoneCallRecord] {
        guard usesDefaultDialer else { return [] }
        if #available(iOS 26, *) {
            let results = try await ConversationHistoryManager.sharedInstance.recentConversations(
                matching: #Predicate<ConversationHistoryManager.RecentConversation> { _ in true })
            return results.compactMap { call in
                guard let number = call.handles.first(where: { $0.type == .phoneNumber })?.value else { return nil }
                let outcome: PhoneCallOutcome
                switch call.status {
                case .connected: outcome = .completed
                case .missed: outcome = .missed
                case .answeredElsewhere: outcome = .answeredElsewhere
                case .cancelled: outcome = .cancelled
                case .unknown: outcome = .failed
                @unknown default: outcome = .failed
                }
                return PhoneCallRecord(id: call.id, person: PhoneNumber.person(number), date: call.date,
                                       duration: max(0, Int(call.duration)), direction: call.direction == .incoming ? .incoming : .outgoing,
                                       outcome: outcome, voice: .unknown)
            }
        }
        return []
    }
}

import AVFAudio
import XCTest
@testable import Callshield

final class DeepfakeIntegrationTests: XCTestCase {
    private let now = Date(timeIntervalSince1970: 1_800_000_000)

    private func fixtureObjects() throws -> [[String: Any]] {
        let url = try XCTUnwrap(Bundle(for: Self.self).url(forResource: "deepfake-wire", withExtension: "json"))
        let root = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
        return try XCTUnwrap(root["cases"] as? [[String: Any]])
    }
    private func payload(named name: String) throws -> [String: Any] {
        let item = try XCTUnwrap(try fixtureObjects().first { $0["name"] as? String == name })
        return try XCTUnwrap(item["payload"] as? [String: Any])
    }
    private func decode(_ object: [String: Any]) throws -> DeepfakeUpdate {
        try XCTUnwrap(DeepfakeUpdate.decode(JSONSerialization.data(withJSONObject: object)))
    }

    func testPythonRiskEngineFixturesDriveEveryVoiceState() throws {
        for item in try fixtureObjects() {
            let update = try decode(XCTUnwrap(item["payload"] as? [String: Any]))
            XCTAssertEqual(update.assessment(at: now).state.rawValue, item["expected"] as? String, item["name"] as? String ?? "")
        }
    }
    func testMalformedMessagesCannotBecomeVoiceLabels() throws {
        let complete = try payload(named: "high")
        for key in ["schema", "type", "room", "callerIdentity", "streamID", "sequence", "model", "deepfake"] {
            var object = complete; object[key] = nil
            XCTAssertNil(DeepfakeUpdate.decode(try JSONSerialization.data(withJSONObject: object)), key)
        }
        for (key, value) in [("schema", 2), ("sequence", 0)] {
            var object = complete; object[key] = value
            XCTAssertNil(DeepfakeUpdate.decode(try JSONSerialization.data(withJSONObject: object)))
        }
        var object = complete
        var evidence = try XCTUnwrap(object["deepfake"] as? [String: Any])
        evidence["p_smoothed"] = 1.1; object["deepfake"] = evidence
        XCTAssertNil(DeepfakeUpdate.decode(try JSONSerialization.data(withJSONObject: object)))
        var status = try payload(named: "waiting"); status["state"] = "human"
        XCTAssertNil(DeepfakeUpdate.decode(try JSONSerialization.data(withJSONObject: status)))
        XCTAssertNil(DeepfakeUpdate.decode(Data("not json".utf8)))
        XCTAssertNil(DeepfakeUpdate.decode(Data(repeating: 32, count: 16_385)))
    }
    func testScopeOrderingRestartAndTimeoutRecovery() throws {
        var monitor = DeepfakeMonitor()
        let object = try payload(named: "high")
        let update = try decode(object)
        func receive(_ value: DeepfakeUpdate, room: String = "call-test", caller: String = "sip-test", agent: Bool = true) -> DeepfakeAssessment? {
            monitor.receive(value, room: room, callerIdentity: caller, isAgent: agent, at: now)
        }
        XCTAssertNil(receive(update, room: "other-call"))
        XCTAssertNil(receive(update, caller: "other-caller"))
        XCTAssertNil(receive(update, agent: false))
